package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_subtract_TriageGen1Test {

    @Test
    public void testSubtract_NormalValues() {
        Complex c1 = new Complex(5.0, 3.0);
        Complex c2 = new Complex(2.0, 1.0);
        Complex expected = new Complex(3.0, 2.0);
        Complex result = c1.subtract(c2);

        assertEquals("Real part should be 3.0", 3.0, result.getReal(), 1e-10);
        assertEquals("Imaginary part should be 2.0", 2.0, result.getImaginary(), 1e-10);
        assertEquals(expected, result);
    }














}

