        Complex c1 = new Complex(1.0000000000001, 1.0);
        Complex c2 = new Complex(1.0, 1.0);
        Complex result = c1.subtract(c2);

        assertEquals(0.0000000000001, result.getReal(), 1e-15);
        assertEquals(0.0, result.getImaginary(), 1e-15);
    }
